      "keystrokes": "cat << 'EOF' > parse_results.py
import json
import csv

with open('audit_results.json', 'r') as f:
    data = json.load(f)

results = []
if 'Results' in data:
    for result in data['Results']:
        if 'Vulnerabilities' in result:
            for vuln in result['Vulnerabilities']:
                package = vuln.get('PkgName', 'N/A')
                version = vuln.get('InstalledVersion', 'N/A')
                cve_id = vuln.get('VulnerabilityID', 'N/A')
                severity = vuln.get('Severity', 'N/A')

                # Get CVSS score (preferring NVD or GHSA if available)
                cvss_score = 'N/A'
                cvss_data = vuln.get('CVSS', {})
                if cvss_data:
                    # Try to find a representative score
                    for source, values in cvss_data.items():
                        if 'V3Score' in values:
                            cvss_score = values['V3Score']
                            break
                        elif 'V2Score' in values:
                            cvss_score = values['V2Score']
                            break

                fixed_version = vuln.get('FixedVersion', 'N/A')
                title = vuln.get('Title', vuln.get('Description', 'N/A')).replace('\n', ' ').replace('\r', '')
                url = vuln.get('PrimaryURL', 'N/A')

                results.append({
                    'Package': package,
                    'Version': version,
                    'CVE_ID': cve_id,
                    'Severity': severity,
                    'CVSS_Score': cvss_score,
                    'Fixed_Version': fixed_version,
                    'Title': title,
                    'Url': url
                })

with open('/root/security_audit.csv', 'w', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=['Package', 'Version', 'CVE_ID', 'Severity', 'CVSS_Score', 'Fixed_Version', 'Title', 'Url'])
    writer.writeheader()
    for row in results:
        writer.writerow(row)
EOF
",
      "duration": 0.5
    },
    {
      "keystrokes": "python3 parse_results.py
",
      "duration": 0.5
    }
  ]
}

